const workflowId = $('Webhook').item.json.body['Workflow ID'];
let tags = $('Split Out').item.json.tags;

// 1. Process the tags to get the last one
let lastTag = "";
if (tags) {
  if (Array.isArray(tags)) {
    lastTag = tags.length > 0 ? tags[tags.length - 1] : "";
  } else if (typeof tags === 'string') {
    lastTag = tags.split(',').pop().trim();
  } else {
    lastTag = String(tags);
  }
}

// 2. Logic: If ID exists, use ID. Else, use Name.
// This removes the semicolon that was causing the 422 error.
let formula = "";

if (workflowId) {
  formula = `{ID} = "${workflowId}"`;
} else if (lastTag) {
  // Use .replace() to ensure any double quotes in the tag name don't break Airtable
  formula = `{Name} = "${lastTag.replace(/"/g, '\\"')}"`;
}

return { airtableFormula: formula };

